head.script:
scwin.onpageload = function () {
    let arr = [
        { "name" : "노트북", "p_text" : "1250000", "p_area" : "1250000" },
        { "name" : "모니터", "p_text" : "320000", "p_area" : "320000" }
    ];
    dlt_a.setJSON(arr);
    dlt_b.setJSON(arr);
};

// customFormatter : 두번째 파라미터(포맷된 값) 앞에 "★ " 를 붙여 반환
scwin.fmt_star = function (data, formattedData, rowIndex, columnIndex) {
    return "★ " + formattedData;
};

// displayFormatter : 천 단위 구분 + " 원"
scwin.formatter_won = function (value) {
    if (value === "" || value === null || typeof value === "undefined") {
        return value;
    }
    return WebSquare.text.formatCurrency(String(value), "#,###") + " 원";
};

// 각 그리드 Row 0 의 화면 표시값 출력 (text / textarea Column)
scwin.btn_check_onclick = function (e) {
    let grds = [["A", grd_a], ["B", grd_b]];
    for (let i = 0; i < grds.length; i++) {
        let grd = grds[i][1];
        scwin.setReturnValue("[" + grds[i][0] + "] text : " + scwin.getCellText(grd, 0, "p_text") + " / textarea : " + scwin.getCellText(grd, 0, "p_area"));
    }
};

// 화면에 표시된 셀 텍스트
scwin.getCellText = function (grd, rowIndex, colId) {
    let el = document.getElementById(grd.id + "_cell_" + rowIndex + "_" + grd.getColumnIndex(colId));
    return el ? el.innerText.replace(/\n/g, " ").trim() : "(셀 없음)";
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
